   "sez": "economia",
   "titolo": "Paraguay, il crac della banca Ueno travolge il presidente Peña",
   "orig": "How Paraguay’s Ueno collapse is only its latest banking crisis",
   "lead": "Il sistema bancario del Paraguay affronta una pesante ondata di instabilità a seguito del collasso dell'istituto Ueno. La crisi ha attirato forti critiche nei confronti del presidente Santiago Peña, finito nel mirino per i suoi presunti collegamenti con la società controllante della banca fallita. Si tratta dell'ennesima turbolenza finanziaria che colpisce il Paese sudamericano, riaccendendo il dibattito sulla regolamentazione del credito privato e sulla trasparenza dei rapporti tra il vertice delle istituzioni pubbliche e i gruppi d'affari nazionali. Lo riferisce Al Jazeera.",
   "more": [
    "La stabilità finanziaria in America Latina è stata storicamente messa a dura prova da ricorrenti crisi bancarie legate a carenze nella vigilanza creditizia. Quando gli istituti di credito affrontano dissesti improvvisi, i legami tra potere politico e proprietà societarie tendono a inasprire le tensioni istituzionali e la sfiducia popolare."
   ],
