   "titolo": "Crisi bancaria in Paraguay: avviato l'impeachment per il presidente Peña",
   "orig": "Paraguay resumes Pena impeachment proceedings as financial crisis deepens",
   "lead": "In Paraguay il Parlamento ha riaperto la procedura per la messa in stato d'accusa del presidente Santiago Peña, mentre peggiora la situazione economica e finanziaria nazionale. Il caos politico è scoppiato dopo il dissesto di una banca digitale, un crac di vasta portata che ha bloccato i conti correnti lasciando circa metà della popolazione senza alcuna possibilità di accedere ai propri risparmi. L'episodio ha scatenato una gravissima emergenza sociale e ha spinto le forze politiche a chiedere la destituzione del capo dello Stato. Lo riferisce Al Jazeera.",
   "more": [
    "L'impeachment in Paraguay è uno strumento costituzionale che consente al Congresso di rimuovere il presidente in caso di cattivo esercizio delle funzioni. La rapida ascesa dei servizi bancari interamente digitali senza adeguate riserve di garanzia ha aumentato la vulnerabilità dei consumatori in molti mercati emergenti."
   ],
