   "id": "z6f9473e0",
   "sez": "mondo",
   "titolo": "Guerra tra Stati Uniti e Iran, smentiti tre filmati virali creati con l'IA",
   "orig": "Fact check: Three viral Iran war posts debunked",
   "lead": "A seguito dell'attacco condotto dagli Stati Uniti contro l'Iran, sui social network si è diffusa un'ampia serie di contenuti visivi drammatici che sostengono la ripresa di violenti scontri armati. Un'indagine condotta dai fact-checker di Deutsche Welle ha smentito tre filmati particolarmente condivisi, dimostrando che si tratta di immagini generate da sistemi di intelligenza artificiale, video riciclati da conflitti passati o post fuorvianti pubblicati da account non verificati per disinformare il pubblico online. Lo riferisce Deutsche Welle.",
   "more": [
    "Nei contesti di crisi bellica, l'uso di modelli generativi di intelligenza artificiale facilita la rapida creazione di prove visive manipolate ma realistiche. Gli esperti di analisi digitale utilizzano tecniche di verifica delle immagini, metadati e geolocalizzazione per rintracciare la vera origine dei filmati ed evitare la proliferazione di notizie false."
   ],
