   "id": "ze01c54ac",
   "sez": "dibattito",
   "titolo": "Francia, il rincaro del debito pubblico limita le riforme su scuola e spesa",
   "orig": "Protests and reforms: France's rising debt costs threaten stability",
   "lead": "In Francia il governo intende destinare quattro miliardi di euro supplementari al settore dell'istruzione pubblica, mentre nel Paese continuano proteste su scala nazionale. Al centro del confronto c'è la sostenibilità dei conti pubblici: a fronte di un debito statale in crescita e dell'aumento degli interessi passivi, economisti e istituzioni si interrogano sui reali margini di manovra dell'esecutivo. I sindacati chiedono maggiori risorse per i servizi pubblici essenziali, mentre gli analisti avvertono che i costi crescenti di rifinanziamento rischiano di compromettere la stabilità finanziaria dello Stato.",
   "more": [
    "La crescita dei tassi di interesse sui titoli di Stato aumenta il costo del servizio del debito per i governi europei, riducendo le risorse destinate alla spesa ordinaria. Il confronto tra la necessità di mantenere il rigore di bilancio e quella di finanziare servizi fondamentali come scuola e sanità impegna gran parte delle democrazie occidentali."
   ],
