   "sez": "musica",
   "titolo": "La Roux pubblica il quarto album 'Cabin Fever' dopo sei anni di assenza",
   "orig": "La Roux: Old Flames review – a breezy, hook-packed twist on a breakup album",
   "lead": "La cantante britannica La Roux, nome d'arte di Elly Jackson, torna sulle scene musicali con la pubblicazione del suo quarto album in studio intitolato Cabin Fever. Il disco, uscito a sei anni dal precedente lavoro, riflette le profonde trasformazioni vissute dall'artista negli ultimi tempi, segnati dalla fine di una relazione durata diciassette anni, da diagnosi di autismo e deficit di attenzione, e dal superamento della dipendenza da cannabis. L'opera combina melodie pop accattivanti con sonorità tipiche del genere R&B degli anni Duemila.",
   "more": [
    "La Roux ha raggiunto la notorietà globale nel 2009 grazie a celebri brani synth-pop come In for the Kill e Bulletproof. Negli ultimi decenni l'industria musicale ha visto molti artisti prolungare i tempi di gestazione dei propri dischi per elaborare cambiamenti stilistici e affrontare percorsi complessi di salute mentale e crescita personale."
   ],
