   "id": "z3a440fa6",
   "sez": "dibattito",
   "titolo": "Fisco e servizi pubblici, la proposta di un contributo di solidarietà sui grandi redditi",
   "orig": "Landini (CGIL): “Non è vero che non ci sono soldi, 25 miliardi per la scuola e la sanità da chi guadagna oltre 2 milioni di euro”",
   "lead": "In Italia il segretario generale della CGIL, Maurizio Landini, ha proposto l'introduzione di un contributo di solidarietà dell'uno percento sui redditi superiori ai due milioni di euro all'anno. Secondo il sindacato, questa misura consentirebbe di reperire circa venticinque miliardi di euro da destinare in primo luogo alla scuola pubblica, oltre che alla sanità, al pubblico impiego e al rilancio delle politiche industriali. La proposta riapre il confronto politico sul finanziamento dei servizi essenziali, sull'equità del sistema tributario e sull'utilizzo della leva fiscale per redistribuire la spesa pubblica verso l'istruzione.",
   "more": [
    "Il dibattito sulla tassazione progressiva e sui contributi straordinari per i patrimoni più elevati vede contrapposte diverse visioni economiche. Da un lato i sostenitori chiedono maggiori risorse per sostenere il welfare e ridurre le disparità sociali, mentre i contrari ritengono che aliquote troppo elevate possano scoraggiare gli investimenti privati e favorire la fuga di capitali all'estero."
   ],
