   "sez": "salute",
   "titolo": "Ucraina, riprenderanno entro la fine dell'anno i voli di evacuazione sanitaria",
   "orig": "Ukraine to resume medical air evacuation flights by year-end, PM says",
   "lead": "Il governo ucraino ha approvato i regolamenti necessari per ripristinare entro la conclusione dell'anno i voli per l'evacuazione medica sul territorio nazionale e verso l'estero. Il primo ministro ha spiegato che questi collegamenti aerei speciali serviranno a trasferire pazienti in condizioni critiche, personale specializzato, organi per trapianto e apparecchiature salvavita tra le varie strutture ospedaliere del Paese. Inoltre, il servizio consentirà di trasportare i malati più gravi all'estero per accedere a cure avanzate non disponibili nelle strutture locali colpite dalle ostilità. Lo riferisce The Kyiv Independent.",
   "more": [
    "La chiusura dello spazio aereo civile determinata dalla guerra ha reso estremamente complicati i trasporti sanitari urgenti in Ucraina, costringendo i pazienti a lunghi e rischiosi viaggi in ambulanza verso i confini occidentali. La riattivazione di corridoi di volo controllati mira a ridurre i tempi di soccorso per i malati gravi."
   ],
