   "sez": "viaggi",
   "titolo": "Turismo marittimo, in arrivo una forte espansione delle crociere nelle mete asiatiche",
   "orig": "A cruise boom is about to hit some of our favourite Asian destinations",
   "lead": "Il comparto dei viaggi marittimi si prepara a una forte crescita verso le principali destinazioni turistiche del continente asiatico. Secondo le previsioni degli operatori, un numero crescente di itinerari e navi da crociera collegherà le città portuali e le coste orientali, offrendo maggiori opportunità a chi intende viaggiare via mare nella vasta regione asiatica. L'incremento dell'offerta e la disponibilità di nuove rotte internazionali rappresentano una svolta positiva per i passeggeri alla ricerca di esperienze marittime verso il nord dell'Oceania. Lo riferisce Sydney Morning Herald.",
   "more": [
    "Il settore delle crociere globali ha registrato una rapida ripresa post-pandemica, con le compagnie navali che hanno riposizionato flotte moderne verso i porti dell'Asia orientale e del Sud-est asiatico. L'espansione risponde alla domanda crescente di itinerari multiculturali che combinano tappe in grandi metropoli costiere e arcipelaghi tropicali."
   ],
