   "titolo": "Animazione giapponese, annunciata la prima edizione dei Nippon Anime Awards per il 2027",
   "orig": "Nippon Anime Awards Revealed for 2027",
   "lead": "Nel settore dell'animazione giapponese è stata svelata la nascita di un nuovo premio ufficiale, denominato Nippon Anime Awards. La cerimonia inaugurale dell'evento si terrà il ventuno novembre 2027 per celebrare le produzioni più rilevanti, gli artisti e gli studi che compongono l'industria degli anime. Il riconoscimento punta a valorizzare le opere di rilievo artistico e l'impatto culturale dei cartoni animati nipponici, offrendo una nuova prestigiosa vetrina per i creatori in un momento di enorme espansione internazionale per l'intero comparto. Lo riferisce Crunchyroll News.",
   "more": [
    "L'industria degli anime giapponesi ha conquistato un vasto pubblico globale grazie alla diffusione delle piattaforme di streaming su scala mondiale. La creazione di cerimonie dedicate risponde all'esigenza di premiare l'eccellenza tecnica e narrativa di sceneggiatori, animatori e registi che contribuiscono a uno dei settori culturali più esportati del Giappone."
   ],
