   "lead": "Il calendario culturale di Chisinau per la giornata del 7 novembre propone diversi appuntamenti dedicati al teatro e ai burattini. Presso il centro culturale Odeon, gli attori della compagnia Planeta Clounella portano in scena la rappresentazione intitolata «The Doughnut». Contemporaneamente, il teatro municipale dei burattini Guguta accoglie il pubblico con lo spettacolo intitolato «In This Life». Entrambi gli eventi sono previsti a partire dalle ore 11:00 per coinvolgere spettatori di diverse fasce di età nella capitale moldava. Lo riferisce IPN (inglese).",
