   "id": "z1c035b1b",
   "sez": "spazio",
   "titolo": "La missione Escapade della Nasa sfrutta manovre a fionda per raggiungere Marte",
   "orig": "NASA's Twin Spacecraft Will Execute Powered Slingshot Maneuvers on Their Way to Mars",
   "lead": "Le due sonde gemelle della missione Escapade della Nasa sono dirette verso Marte impiegando speciali manovre di fionda gravitazionale motorizzata per incrementare la propria velocità. La scelta di questa traiettoria si è resa necessaria a causa della partenza avvenuta al di fuori della consueta finestra di lancio verso il pianeta rosso. Una volta giunti a destinazione, i due veicoli spaziali voleranno in formazione ravvicinata con l'obiettivo scientifico di analizzare l'interazione del vento solare con ciò che resta dell'antica magnetosfera marziana. Lo riferisce Universe Today.",
   "more": [
    "L'effetto fionda gravitazionale, noto anche come gravity assist, è una tecnica di navigazione spaziale che sfrutta il campo di gravità e il movimento orbitale di un corpo celeste per modificare la traiettoria e la velocità di una sonda senza consumare grandi quantità di propellente."
   ],
