   "sez": "mondo",
   "titolo": "Le organizzazioni per i diritti umani denunciano il maxiprocesso ai religiosi sciiti in Bahrein",
   "orig": "Rights groups condemn Bahrain's largest mass trial of Shia clerics in history",
   "lead": "In Bahrein si tiene il più grande processo di massa contro religiosi sciiti mai registrato nella storia del Paese, un procedimento che vede sessanta ecclesiastici rischiare pene detentive. Numerose organizzazioni non governative per la tutela dei diritti umani hanno condannato l'azione giudiziaria, accusando l'apparato statale di aver estorto confessioni sotto tortura durante la fase degli interrogatori preliminari. La vicenda ha suscitato vivaci proteste della società civile, sollevando timori per il rispetto delle tutele fondamentali e della libertà religiosa all'interno del regno mediorientale. Lo riferisce Middle East Eye.",
   "more": [
    "Il Bahrein ospita una popolazione a maggioranza sciita, ma è retto da una monarchia sunnita. Le tensioni interne e le denunce di discriminazione settaria sono aumentate significativamente a partire dalle proteste popolari del 2011, che chiedevano riforme democratiche."
   ],
