   "titolo": "L'edilizia residenziale perde posti di lavoro negli Stati Uniti durante il mese di ottobre",
   "orig": "Construction Jobs Declined in October as Residential Contractors Shed 16.4K Workers",
   "lead": "I dati occupazionali del mese di ottobre negli Stati Uniti segnalano una complessiva contrazione dei posti nel settore delle costruzioni, causata principalmente dal comparto residenziale che ha registrato un calo di 16.400 lavoratori. Secondo i rilievi forniti dal Bureau of Labor Statistics, tale flessione non è stata compensata dagli incrementi registrati negli altri rami: le imprese di costruzione generale hanno aggiunto 2.900 posizioni, l'ingegneria civile pesante ha inserito 2.500 addetti e i contratti specialistici non residenziali sono saliti di 7.900 unità. Lo riferisce Engineering News-Record.",
