   "sez": "adolescenti",
   "titolo": "Il Tar della Lombardia respinge il ricorso dei genitori contro la bocciatura al liceo classico",
   "orig": "Italiano, latino e greco con 4, matematica con 5, alunna con “disturbo misto delle capacità scolastiche”. Famiglia fa ricorso al TAR contro la bocciatura, ma i giudici dicono no: ecco perché",
   "lead": "Il Tribunale Amministrativo Regionale per la Lombardia, nella sezione di Brescia, ha respinto il ricorso avanzato dai genitori di una studentessa del liceo classico non ammessa al secondo anno. L'alunna aveva concluso l'anno scolastico con cinque insufficienze gravi, tra cui voti pari a quattro in italiano, latino e greco e un cinque in matematica, a fronte di una diagnosi di disturbo misto delle capacità scolastiche presentata dalla famiglia. Con la sentenza emessa il 13 ottobre, i giudici amministrativi hanno confermato la piena legittimità della decisione presa dal consiglio di classe. Lo riferisce Orizzonte Scuola.",
