   "orig": "Where to Eat Gluten-Free in Montreal",
   "lead": "A Montréal cresce l'offerta gastronomica rivolta a chi cerca piatti privi di glutine, spaziando tra ristoranti tradizionali, locali per spuntini veloci e proposte per aperitivi dedicati. Il critico enogastronomico e autore di viaggi Luke Pyenson ha condotto una panoramica delle realtà culinarie più interessanti della metropoli canadese, selezionando le cucine che garantiscono menu inclusivi senza rinunciare alla qualità culinaria e alla varietà degli ingredienti. La rassegna offre una guida pratica per residenti e visitatori con particolari esigenze alimentari. Lo riferisce Condé Nast Traveler.",
