   "orig": "Build Your PSI Type — Are You a Burst, Rise, or Trance User in PSYREN?",
   "lead": "La piattaforma Crunchyroll News ha presentato un quiz rivolto agli appassionati del manga e anime Psyren per determinare a quale categoria psichica apparterrebbero all'interno della narrazione. Nell'ambientazione dell'opera, le facoltà soprannaturali denominate poteri PSI si articolano principalmente in tre grandi tipologie: utilizzatori di tipo Burst, specializzati nell'emissione di energia, di tipo Rise, incentrati sul potenziamento fisico, e di tipo Trance, legati a capacità mentali e sensoriali. L'iniziativa permette ai fan di verificare virtualmente il proprio profilo all'interno di questo sistema magico. Lo riferisce Crunchyroll News.",
