   "id": "z827da2d6",
   "sez": "sport",
   "titolo": "Il lanciatore indiano Mohammed Shami annuncia il ritiro dal Test cricket",
   "orig": "‘Thank you, Test Cricket’: Shami retires from longest format of the game",
   "lead": "Il giocatore di cricket indiano Mohammed Shami ha annunciato ufficialmente il proprio ritiro dal Test cricket, la forma classica e più prolungata della disciplina sportiva. La decisione è giunta esattamente tredici anni dopo il suo esordio internazionale risalente al 2013 contro le Indie Occidentali. Il lanciatore veloce, che oggi ha 36 anni, conclude il suo percorso con un bilancio complessivo di 229 wicket conquistati in 64 partite ufficiali disputate, avendo giocato la sua ultima gara con la maglia dell'India nel giugno 2023 contro l'Australia prima del congedo affidato ai social.",
   "more": [
    "Il Test cricket rappresenta il formato più antico e prestigioso del cricket internazionale, in cui due squadre si affrontano in un incontro che può durare fino a cinque giorni, mettendo a dura prova la resistenza fisica e le doti tattiche degli atleti."
   ],
