   "orig": "Laos, Russian Region of Tatarstan Discuss New Trade Opportunities",
   "lead": "Il capo della repubblica russa del Tatarstan, Rustam Minnikhanov, ha concluso una visita di due giorni a Vientiane incontrando il primo ministro del Laos, Saleumxay Kommasith, per avviare relazioni commerciali tra le due parti. Durante i colloqui del 4 e 5 novembre, entrambe le delegazioni hanno concordato di sviluppare nuove opportunità di investimento congiunto, definendo i legami economici attuali come praticamente inesistenti. L'obiettivo dichiarato dalle autorità locali è quello di creare partnership stabili in settori strategici per stimolare le rispettive economie. Lo riferisce The Laotian Times.",
