   "titolo": "In Francia si discute della ricomparsa dei gilet gialli tra le nuove proteste giovanili",
   "orig": "Sono tornati i gilet gialli in Francia?",
   "lead": "In Francia è aperto il confronto sulla presenza dei gilet gialli nelle recenti manifestazioni di piazza e sul significato di questa rinnovata visibilità. A differenza delle ondate di protesta degli anni passati, il movimento non assume un ruolo direttivo e non è l'organizzatore delle mobilitazioni attuali. L'abbigliamento catarifrangente, divenuto simbolo storico del malcontento sociale, è stato invece adottato da gruppi di giovani manifestanti che ne hanno mutuato l'estetica, collocando i militanti storici in una posizione di secondo piano rispetto alle nuove rivendicazioni generazionali. Lo riferisce Il Post.",
   "more": [
    "Il movimento dei gilet gialli nacque in Francia nell'autunno del 2018 per protestare inizialmente contro l'aumento delle accise sui carburanti, prima di allargarsi a rivendicazioni sul potere d'acquisto, sulla giustizia fiscale e sull'introduzione di referendum di iniziativa cittadina."
   ],
