   "lead": "Il festival musicale Dias do Jazz giunge a conclusione nella cittadina portoghese di Caldas da Rainha con gli appuntamenti previsti durante il fine settimana al Centro Culturale e dei Congressi. Il programma della manifestazione culmina con l'esibizione dell'Henri Texier Quartet, accompagnata da un secondo concerto serale sul medesimo palco. Gli organizzatori hanno inoltre predisposto un momento di incontro informale aperto che permette al pubblico presente di dialogare da vicino con i musicisti ospiti, completando il cartellone concertistico del polo culturale. Lo riferisce RTP.",
