   "id": "za4b12283",
   "sez": "spazio",
   "titolo": "La Russia accelera lo sviluppo della rete satellitare Rassvet per contrastare Starlink",
   "orig": "Fears Starlink, builds one of its own: Russia rushes to scale up Rassvet",
   "lead": "Il Consiglio di sicurezza della Federazione Russa ha disposto una rapida espansione della costellazione satellitare di comunicazioni denominata Rassvet per fronteggiare i servizi concorrenti come Starlink. Nel corso dell'anno in corso sono stati posizionati in orbita 32 vettori per supportare le linee di comunicazione delle forze armate in Ucraina, sebbene l'infrastruttura mostri ancora criticità con coperture territoriali ridotte e collegamenti intermittenti su aree specifiche. Da Mosca si ribadiscono i presunti pericoli per la sicurezza legati all'operatività di reti satellitari occidentali su territori sovrani. Lo riferisce Times of India.",
   "more": [
    "Le costellazioni satellitari in orbita terrestre bassa (Leo) consentono trasmissioni dati a banda larga e bassa latenza, risultando fondamentali sia per le telecomunicazioni civili in zone remote sia per la gestione operativa e tattica sul campo militare."
   ],
