   "titolo": "Frena la fiducia nelle costruzioni negli Stati Uniti nonostante i cantieri attivi",
   "orig": "Construction’s latest economic reports reveal less confidence despite more work",
   "lead": "I più recenti rapporti economici sul settore ingegneristico ed edile negli Stati Uniti evidenziano un calo della fiducia tra gli operatori, pur in presenza di una mole elevata di commesse. Il clima di pessimismo è alimentato dai costi di costruzione rimasti su livelli elevati e dalla debolezza della domanda complessiva al di fuori delle attività trainate dalla forte espansione dei centri di elaborazione dati. Questa disparità settoriale genera incertezze sull'andamento delle future gare d'appalto e sulla redditività delle imprese costruttrici. Lo riferisce Construction Dive.",
