   "orig": "Supplenze al 30 giugno, quando la scuola può nominare da graduatoria di istituto e perché anche un’ora può vincolare il docente. Pillole di Question Time",
   "lead": "Durante una sessione di approfondimento online, la segretaria nazionale del sindacato della scuola Anief ha illustrato i meccanismi normativi che regolano le supplenze fino al 30 giugno e le chiamate dirette da parte dei singoli istituti scolastici. Tra gli elementi affrontati è stato chiarito in quali circostanze un istituto può attingere direttamente alle graduatorie di istituto rispetto alle graduatorie provinciali per le supplenze. Inoltre è stato spiegato il motivo per cui anche l'accettazione di un incarico per un solo orario d'insegnamento possa generare un vincolo formale per il docente. Lo riferisce Orizzonte Scuola.",
