   "orig": "11 Gorgeous US Ski Vacation Homes Built for Fresh Powder and Easy Slope Access",
   "lead": "Per la stagione sciistica negli Stati Uniti viene presentata una selezione di undici case vacanza progettate per gli appassionati della neve fresca, dotate della comodità dell'accesso sci ai piedi per entrare immediatamente sui comprensori alpini. Le soluzioni abitative selezionate spaziano da appartamenti esclusivi situati nella rinomata località di Aspen fino a baite accoglienti tra i boschi di Stowe, nello stato del Vermont. Gli alloggi mettono a disposizione soluzioni di soggiorno pensate per agevolare le partenze e la pianificazione dei viaggi invernali. Lo riferisce Condé Nast Traveler.",
