   "lead": "La produzione dell'adattamento anime Magical Sisters Lulutto Lilly ha annunciato l'ingresso ufficiale di tre interpreti per dare voce ad altrettante creature magiche della serie. La novità riguarda la seconda parte della programmazione televisiva, attualmente in corso di trasmissione sulle emittenti giapponesi e sulle piattaforme di streaming. La trama della serie, incentrata sulle peripezie di giovani maghe, arricchisce così il proprio cast animato con nuovi personaggi fantastici che interagiranno con le sorelle protagoniste durante gli episodi della stagione. Lo riferisce Crunchyroll News.",
