   "lead": "Il rapper statunitense Macklemore ha sollevato una forte controversia denunciando il rifiuto di diversi grandi palazzetti dello sport americani, tra cui il Madison Square Garden e il Kia Forum, a ospitare le date della sua tournée di concerti benefici a sostegno della causa palestinese. L'artista ha dichiarato che la disponibilità delle sale è venuta meno non appena le strutture hanno appreso lo scopo benefico dell'evento, sottolineando di non aver mai vissuto una simile preclusione in oltre vent'anni di concerti dopo le sue prese di posizione pubbliche sul conflitto a Gaza.",
