   "orig": "Famalicão - Arouca",
   "lead": "La massima serie del campionato di calcio portoghese apre l'undicesima giornata con la sfida tra le formazioni di Famalicão e Arouca, in campo presso lo stadio di Vila Nova de Famalicão. Gli ospiti si presentano alla trasferta con l'obiettivo di confermare il momento positivo che li vede occupare la quinta posizione nella classifica del torneo. I padroni di casa cercano punti per migliorare la propria graduatoria davanti al proprio pubblico, in una partita che inaugura il fine settimana sportivo della Primeira Liga lusitana. Lo riferisce RTP.",
