   "titolo": "La tutela degli archivi di architettura milanesi tra fondazioni e università",
   "orig": "Archivi, come cambiano i luoghi della memoria",
   "lead": "Alcune recenti vicende riguardanti gli archivi di progettazione a Milano sollecitano una riflessione sulla gestione e sulla fruibilità dei luoghi della memoria materiale. A maggio del 2026 i disegni originali dell'architetto Piero Portaluppi sono stati trasferiti dalla storica sede di via Morozzo della Rocca a una nuova collocazione. Attraverso il contributo dello storico Fulvio Irace, viene tracciata una mappa delle relazioni tra eredi, fondazioni, università ed enti pubblici per capire come salvaguardare e rendere accessibili patrimoni documentali che rischiano la dispersione. Lo riferisce Il Giornale dell'Architettura.",
