   "titolo": "Schlein chiede la riscrittura della manovra e critica i tagli a scuola e docenti",
   "orig": "Manovra, Schlein: “Va completamente riscritta. Non solo hanno provato a cacciare i bambini stranieri, ora cacciano anche gli insegnanti”",
   "lead": "A margine di un incontro del Partito Democratico dedicato ai temi della giustizia a Bologna, la segretaria Elly Schlein ha chiesto la riscrittura totale della legge di bilancio predisposta dal governo, annunciando un'azione coordinata con le altre forze parlamentari di opposizione. Nel suo intervento, la leader politica ha attaccato le scelte dell'esecutivo affermando che dopo aver tentato di escludere i bambini stranieri dalle aule adesso si allontanano anche gli insegnanti, contestando l'orientamento complessivo della spesa pubblica riservata al comparto dell'istruzione e dei servizi educativi. Lo riferisce Orizzonte Scuola.",
