   "id": "zb4b35135",
   "sez": "spazio",
   "titolo": "Specchi vibranti di luce simulano in laboratorio l'orizzonte degli eventi di un buco nero",
   "orig": "Vibrating mirrors of light create analog of a black hole event horizon",
   "lead": "I dispositivi ottici a cavità, costituiti da coppie di specchi capaci di intrappolare la luce, sono impiegati per realizzare un analogo sperimentale dell'orizzonte degli eventi dei buchi neri. Tali strumenti sono fondamentali per orologi atomici, laser e sensori di precisione: secondo alcune teorie fisiche, una rapida variazione della distanza tra gli specchi costringerebbe le onde interne a raggrupparsi in impulsi brevi ed estremamente intensi. Questa previsione teorica non aveva mai ricevuto finora una verifica sperimentale diretta per studiare fenomeni gravitazionali estremi in laboratorio. Lo riferisce Phys.org – Spazio.",
   "more": [
    "L'orizzonte degli eventi rappresenta il confine teorico attorno a un buco nero oltre il quale la velocità di fuga supera quella della luce, rendendo impossibile la fuoriuscita di qualsiasi particella o radiazione elettromagnetica verso l'esterno."
   ],
