   "orig": "Pretty Things: solo ceramic exhibition",
   "lead": "La città di Limassol ospita nel mese di novembre la mostra personale di opere in ceramica intitolata Pretty Things, realizzata dall'artista Anastasia Fainberg. L'esposizione assume un doppio significato culturale: oltre a presentare la nuova produzione artistica dell'autrice, segna formalmente l'apertura di una nuova fase per il Myrianthe Sozou Studio, situato nel centro storico della località cipriota. L'iniziativa arricchisce il calendario degli appuntamenti culturali di novembre, offrendo al pubblico una rassegna dedicata alle creazioni recenti della scultrice all'interno di uno spazio rinnovato. Lo riferisce Cyprus Mail.",
   "more": [
    "La ceramica artistica contemporanea combina tecniche artigianali tradizionali di modellazione e cottura dell'argilla con la ricerca estetica e concettuale. Spazi espositivi e atelier dedicati consentono agli autori di valorizzare il lavoro materico all'interno delle comunità urbane locali, favorendo l'incontro tra maestranze e pubblico."
   ],
