   "sez": "economia",
   "titolo": "Mosca riduce l'avanzata in Ucraina e fatica a vendere il proprio gasolio",
   "orig": "Russia’s land gains in Ukraine dwindle as its diesel reportedly goes unsold",
   "lead": "La Russia sta registrando un rallentamento dei propri guadagni territoriali sul fronte ucraino, mentre aumentano le difficoltà sul piano delle esportazioni di idrocarburi. In base a quanto riportato, l'esercito di Mosca continua a subire perdite sul campo di battaglia, mentre il gasolio russo rimarrebbe in larga parte invenduto a causa del presunto rifiuto dei commercianti statunitensi di rispettare gli accordi sulle forniture siglati tra l'amministrazione guidata da Donald Trump e Vladimir Putin. Questa combinazione di pressioni militari ed economiche complica la strategia russa nel conflitto. Lo riferisce Al Jazeera.",
   "more": [
    "I proventi generati dall'esportazione di petrolio e derivati raffinati, tra cui il gasolio, rappresentano una quota fondamentale delle entrate fiscali della Federazione Russa. Il blocco o la difficoltà di collocamento delle merci energetiche sui mercati globali riduce i flussi di valuta estera a disposizione del bilancio statale, incidendo anche sulle risorse finanziarie destinate al settore della difesa."
   ],
