   "titolo": "Gli U2 annunciano un terzo concerto a Milano nel tour del 2027",
   "orig": "U2: annunciata una nuova data allo stadio San Siro di Milano – Il calendario completo del tour",
   "lead": "La celebre band irlandese degli U2 ha annunciato ufficialmente una terza data dal vivo allo stadio San Siro di Milano, fissata per il 9 luglio 2027. Il gruppo, composto da Bono, The Edge, Adam Clayton e Larry Mullen Jr., ha deciso di raddoppiare l'offerta per il pubblico italiano dopo il rapido esaurimento dei biglietti relativi ai primi due concerti già calendarizzati per il 5 e il 6 luglio 2027. I tagliandi per assistere al nuovo spettacolo saranno messi in vendita a partire dal prossimo 10 novembre. Lo riferisce OndaRock.",
   "more": [
    "Lo stadio Giuseppe Meazza di San Siro a Milano è uno dei principali impianti europei per i grandi concerti internazionali, capace di accogliere decine di migliaia di spettatori. Le tournée mondiali di gruppi storici richiedono pianificazioni logistiche con anni di anticipo per coordinare le tappe negli stadi e le prevendite dei biglietti."
   ],
