   "sez": "sport",
   "titolo": "Premier League: l'Everton di David Moyes sfida il Coventry City",
   "orig": "Everton v Coventry City: Premier League – live",
   "lead": "L'Everton scende in campo contro il Coventry City nella sfida serale della Premier League, con l'opportunità di compiere un significativo balzo in avanti nella classifica del campionato inglese. Una vittoria consentirebbe alla formazione guidata dall'allenatore David Moyes di superare i rivali del Liverpool, mentre un successo molto largo permetterebbe addirittura di scavalcare il Chelsea al quarto posto. La squadra di Moyes sta superando le basse aspettative della vigilia, nate da una sessione di calciomercato poco brillante, mentre il Coventry City cerca punti preziosi nella trasferta. Lo riferisce The Guardian.",
   "more": [
    "La Premier League è la massima divisione professionistica del calcio inglese, nota per l'elevato livello di competitività e per la distribuzione dei proventi commerciali e televisivi. I piazzamenti nelle prime quattro posizioni della graduatoria finale garantiscono l'accesso diretto alla UEFA Champions League della stagione successiva."
   ],
