   "sez": "cultura",
   "titolo": "Collectible porta il design d'avanguardia a New York in un ex cinema AMC",
   "orig": "Want an escape from AI slop? Head to Collectible, an avant-garde design fair, happening in New York this weekend",
   "lead": "La fiera Collectible torna a New York fino a domenica 8 novembre, offrendo una vetrina dedicata al design da collezione e all'avanguardia creativa contemporanea. L'evento espositivo è ospitato negli spazi inconsueti di un ex cinema AMC e viene presentato come un'alternativa materiale e autentica rispetto alla saturazione di contenuti visivi generati dall'intelligenza artificiale. L'appuntamento permette a gallerie, progettisti e curatori internazionali di esporre arredi sperimentali, pezzi unici e prototipi, focalizzandosi sull'artigianato d'autore e sull'innovazione formale all'interno del vivace panorama culturale della metropoli statunitense. Lo riferisce Wallpaper*.",
   "more": [
    "Il design da collezione si colloca al confine tra arte figurativa, architettura d'interni e artigianato d'alto livello, privilegiando produzioni in serie limitata o manufatti singoli. Manifestazioni di questo tipo offrono visibilità commerciale e critica a designer indipendenti e studi emergenti nei mercati artistici globali."
   ],
