   "sez": "italia",
   "titolo": "Scuola primaria: le prospettive di immissione in ruolo per l'educazione motoria",
   "orig": "Concorso 2023 ed. motoria alla primaria, il ruolo arriverà (prima o poi). Assunzioni anche da elenco regionale",
   "lead": "I candidati del concorso per l'insegnamento dell'educazione motoria nella scuola primaria attendono la stabilizzazione, con le future assunzioni che avverranno progressivamente anche attingendo dagli elenchi regionali. La procedura selettiva, bandita con decreto ministeriale nell'agosto del 2023 per assegnare 1.740 posti comuni vacanti nell'anno scolastico 2023/2024, costituisce al momento l'unico concorso svolto per questo profilo specialistico. Nonostante le tempistiche prolungate, l'immissione in ruolo resta confermata per gli idonei inseriti nelle graduatorie, mentre prosegue la gestione delle disponibilità di cattedra negli istituti scolastici italiani. Lo riferisce Orizzonte Scuola.",
   "more": [
    "L'introduzione dei docenti specialisti di educazione motoria nelle quarte e quinte classi della scuola primaria italiana è stata prevista dalla legge di bilancio per il 2022. L'obiettivo della misura è promuovere stili di vita sani e una corretta attività fisica fin dai primi anni di istruzione obbligatoria."
   ],
