   "titolo": "Ad Accra si apre la Black Star Fashion Week con dibattiti e sfilate",
   "orig": "Black Star fashion week kicks off in Accra with summit",
   "lead": "La capitale ghanese ha ospitato l'apertura ufficiale della Black Star Fashion Week, una manifestazione dedicata alla valorizzazione della moda contemporanea e delle industrie creative del continente africano. La prima giornata della kermesse ad Accra si è articolata attraverso un summit comprensivo di corsi specialistici, tavole rotonde, presentazioni ed esposizioni di settore. L'iniziativa ha offerto a stilisti, imprenditori e addetti ai lavori uno spazio strutturato per condividere competenze tecniche, analizzare le tendenze emergenti e sviluppare reti di contatti professionali sul mercato internazionale. Lo riferisce 3News.",
   "more": [
    "Il settore della moda in Africa occidentale sta vivendo una fase di crescente rilevanza economica e culturale, grazie all'impiego di tessuti tradizionali uniti al design contemporaneo. Eventi internazionali favoriscono la commercializzazione dei marchi locali e la formazione di nuove professionalità nella filiera tessile."
   ],
