   "id": "zda6ff162",
   "sez": "salute",
   "titolo": "Mark Dybul nominato alla guida del Fondo Globale per la sanità",
   "orig": "[World Report] Global Fund appoints Mark Dybul as head",
   "lead": "Il Fondo Globale per la lotta all'Aids, alla tubercolosi e alla malaria ha designato Mark Dybul come nuovo vertice dell'organizzazione internazionale. La nomina è stata accolta con grande favore dai leader sanitari internazionali, che considerano l'incarico fondamentale all'interno di un panorama medico e geopolitico mondiale in rapida e complessa evoluzione. Dybul guiderà l'ente con l'obiettivo di coordinare le risorse finanziarie e mantenere alta l'efficacia degli interventi volti a contrastare le grandi epidemie nei Paesi a basso e medio reddito. Lo riferisce The Lancet.",
   "more": [
    "Il Fondo Globale è un'organizzazione multilaterale pubblico-privata istituita nel 2002 per mobilitare e investire miliardi di dollari ogni anno nella prevenzione e nel trattamento di Aids, tubercolosi e malaria. L'ente collabora con governi, società civile e comunità locali nei Paesi più vulnerabili."
   ],
