   "sez": "dibattito",
   "titolo": "Trasporti: Italo revoca lo sciopero, stop al servizio locale a Genova e Palermo",
   "orig": "Sciopero treni Italo 9 novembre, l’azienda: “Revocato dai sindacati”. Tpl, stop a Palermo e Genova",
   "lead": "In Italia resta aperto il dibattito sulle condizioni di lavoro e i salari nel settore dei trasporti pubblici e ferroviari. I sindacati hanno annunciato la revoca della mobilitazione prevista per il 9 novembre sul personale ferroviario di Italo, mentre sono state confermate le proteste nei trasporti urbani a Palermo e Genova. Nelle due città il personale delle aziende municipalizzate Amat e Amt si è fermato per rivendicare aumenti stipendiali e un rinnovo dei contratti collettivi ritenuto congruo, creando disagi alla circolazione dei residenti. Lo riferisce la Repubblica – Economia.",
   "more": [
    "Il trasporto pubblico locale italiano affronta da anni questioni legate all'adeguamento dei contratti collettivi e al reperimento di risorse pubbliche per le aziende municipalizzate. I lavoratori e i sindacati denunciano la perdita di potere d'acquisto dovuta all'inflazione, mentre le amministrazioni locali e le imprese di settore devono conciliare i vincoli di bilancio con l'esigenza di garantire corse regolari e servizi essenziali ai pendolari."
   ],
