   "sez": "cultura",
   "titolo": "Sud Sudan: il museo She Stands chiede partnership per la storia femminile",
   "orig": "She Stands Women’s Museum calls for stronger partnerships to preserve South Sudanese women’s history",
   "lead": "Il museo She Stands Women’s Museum ha rivolto un appello pubblico per istituire collaborazioni nazionali e internazionali più solide allo scopo di tutelare e valorizzare la storia delle donne del Sud Sudan. La richiesta è stata formalizzata durante il pranzo diplomatico annuale dell'organizzazione, organizzato con l'obiettivo di documentare l'apporto femminile ai processi di liberazione e sviluppo del Paese africano. L'istituzione intende promuovere il patrimonio culturale sud-sudanese a livello globale attraverso accordi di cooperazione diplomatica e progetti condivisi di ricerca storica. Lo riferisce Eye Radio.",
   "more": [
    "Il Sud Sudan, indipendente dal 2011 dopo decenni di conflitti civili, è impegnato nella costruzione della propria memoria storica e delle istituzioni culturali. Le donne hanno svolto ruoli rilevanti nella resistenza, nel sostegno comunitario e nella successiva fase di costruzione dello Stato."
   ],
