   "sez": "economia",
   "titolo": "Corea del Nord: raddoppiano i prezzi di carbone e legna a Ryanggang",
   "orig": "Firewood and coal prices double in Ryanggang province",
   "lead": "Nella provincia montuosa di Ryanggang, in Corea del Nord, i prezzi della legna da ardere e del carbone sono raddoppiati in seguito a un'improvvisa e intensa ondata di freddo. Fonti locali segnalano che le temperature nell'area highland sono scese sotto lo zero fin dalla fine di ottobre, mettendo in grave difficoltà le famiglie a basso reddito di città come Hyesan e Samjiyon. Gli abitanti meno abbienti della regione non dispongono delle risorse economiche sufficienti per acquistare combustibile e affrontare la stagione invernale del 2026. Lo riferisce Daily NK.",
   "more": [
    "Gran parte della popolazione nordcoreana al di fuori della capitale fa affidamento su stufe tradizionali alimentate a carbone o biomassa per riscaldare le abitazioni durante i rigidi inverni continentali. Le difficoltà economiche e la scarsità di risorse rendono il mercato informale dei combustibili estremamente volatile in caso di gelate precoci."
   ],
