   "id": "z4cec32ee",
   "sez": "salute",
   "titolo": "L'India impone un tetto ai prezzi di 137 farmaci antitumorali",
   "orig": "[World Report] India to cap the cost of 137 cancer drugs",
   "lead": "L'Autorità nazionale per i prezzi dei prodotti farmaceutici dell'India ha stabilito l'introduzione di un tetto massimo sui margini commerciali applicabili a 137 farmaci antitumorali. Il provvedimento governativo giunge a seguito di una specifica sentenza della Corte Suprema indiana, finalizzata a rendere maggiormente accessibili e calmierate le terapie salvavita per i pazienti oncologici. La decisione interviene sulla catena di distribuzione riducendo i ricarichi sui medicinali critici, con l'obiettivo di contenere i costi sanitari a carico dei cittadini in tutto il territorio nazionale. Lo riferisce The Lancet.",
   "more": [
    "L'India è uno dei principali produttori mondiali di farmaci generici a basso costo, ma la spesa sanitaria privata diretta rimane molto onerosa per gran parte delle famiglie locali. L'intervento delle autorità regolatorie sui prezzi dei medicinali salvavita mira a prevenire l'indebitamento economico dei pazienti affetti da patologie gravi."
   ],
