   "id": "zbbe962ab",
   "sez": "salute",
   "titolo": "Usa: la vittoria dei Democratici ai midterm dà respiro agli ospedali",
   "orig": "STAT+: Democrats’ midterm landslide spells relief for hospitals",
   "lead": "Il netto successo del Partito Democratico alle elezioni di metà mandato negli Stati Uniti d'America apre prospettive favorevoli per la sostenibilità economica degli ospedali e delle strutture sanitarie. In base alle prime valutazioni, la nuova maggioranza parlamentare orienterà i propri sforzi legislativi sull'annullamento dei tagli al programma Medicaid e sull'ulteriore estensione della copertura assicurativa pubblica e privata per la popolazione. Queste iniziative legislative forniranno un sostegno finanziario rilevante ai fornitori di cure sanitarie, riducendo i costi delle prestazioni non rimborsate per i nosocomi statunitensi. Lo riferisce STAT.",
   "more": [
    "Negli Stati Uniti il programma pubblico Medicaid garantisce assistenza sanitaria a milioni di cittadini con redditi bassi ed è cofinanziato dai singoli stati e dal governo federale. Le modifiche legislative ai criteri di eleggibilità e ai rimborsi ospedalieri determinano direttamente il volume di ricavi e la solvibilità dei centri di cura."
   ],
