   "id": "zfe77b042",
   "sez": "prima",
   "titolo": "Il Papa parte per il viaggio in America Latina",
   "orig": "Il Papa in viaggio verso l'America Latina",
   "lead": "Papa Leone XIV è partito da Roma per un viaggio apostolico di 12 giorni in Uruguay, Argentina e Perù, a tre settimane dalla rimozione chirurgica di un tumore al polmone. È il sesto viaggio del pontificato e il più lungo e distante finora compiuto. Il Perù suscita particolare attenzione perché il Papa vi ha vissuto come missionario per quasi vent'anni prima di diventare vescovo. Nei tre Paesi sono previsti incontri pubblici e celebrazioni eucaristiche nelle prossime settimane.",
   "more": [
    "Leone XIV, eletto dopo papa Francesco, aveva subito nelle settimane precedenti un intervento chirurgico al polmone per un tumore, che aveva fatto temere la cancellazione del viaggio. Il legame personale con il Perù, dove è stato missionario e poi vescovo per quasi due decenni, rende la tappa peruviana particolarmente significativa per il pontefice."
   ],
