   "id": "zd6bc5244",
   "sez": "mondo",
   "titolo": "Paraguay, proteste per chiedere conto a Peña del crollo di Ueno Bank",
   "orig": "Protestas en Paraguay para pedir que Peña responda a la justicia por caída de Ueno Bank",
   "lead": "In Paraguay si sono svolte proteste per chiedere che il presidente Santiago Peña risponda davanti alla giustizia per il crollo della banca Ueno. Il Congresso non è riuscito a votare le dimissioni presentate dal presidente per mancanza di quorum, mentre Peña ha dichiarato che intende esercitare il proprio diritto alla difesa. Il Senato ha comunque avviato il giudizio politico contro di lui nonostante la rinuncia annunciata. Il ministro dell'Interno Enrique Riera si è dimesso ed è stato sostituito in via interinale da Carlos Benítez, mentre otto dirigenti della banca sono stati arrestati e milioni di cittadini attendono di recuperare i propri depositi.",
   "more": [
    "La banca Ueno è crollata dopo essere scesa sotto la metà della solvenza minima richiesta dalla legge, provocando le dimissioni del presidente della Banca centrale e l'arresto di otto dirigenti. La crisi finanziaria ha avuto ripercussioni politiche dirette sul presidente Peña, considerato uno dei principali alleati regionali degli Stati Uniti in America Latina."
   ],
