   "id": "zea79e8ce",
   "sez": "sport",
   "titolo": "Cristiano Ronaldo annuncia il ritiro dalla nazionale portoghese",
   "orig": "Cristiano Ronaldo announces retirement from international football",
   "lead": "Cristiano Ronaldo ha annunciato il ritiro dal calcio internazionale, poche settimane dopo un contrasto pubblico con il selezionatore del Portogallo Jorge Jesus sul minutaggio concessogli in campo. L'annuncio chiude una carriera in nazionale lunga e vincente, conclusa però in un clima di polemiche. Diversi commentatori sottolineano il contrasto con il rivale storico Lionel Messi, ritiratosi anch'egli dal calcio internazionale nel corso dell'anno, ma dopo aver guidato l'Argentina a due finali mondiali consecutive, in un epilogo giudicato più sereno.",
   "more": [
    "Ronaldo è stato per anni capitano e principale marcatore della nazionale portoghese, con cui ha vinto l'Europeo del 2016. Nelle ultime settimane erano emerse tensioni con il selezionatore Jorge Jesus riguardo al suo impiego in campo, culminate ora nell'annuncio del ritiro dalla nazionale."
   ],
