   "id": "z6aaeeae7",
   "sez": "mondo",
   "titolo": "Sudan accusa l'Etiopia di sostenere gli attacchi con drone delle Rsf",
   "orig": "Sudan gov’t accuses Ethiopia of backing RSF drone attacks, analysts question UN complaint",
   "lead": "Il governo sudanese ha accusato l'Etiopia di sostenere gli attacchi con drone condotti dalle Forze di supporto rapido (Rsf), i paramilitari in guerra contro l'esercito regolare sudanese, presentando una denuncia alle Nazioni Unite. Alcuni analisti però dubitano della fondatezza dell'accusa. Nel frattempo Sudan ed Etiopia hanno chiuso reciprocamente i rispettivi consolati a causa della guerra civile in corso in Sudan.",
   "more": [
    "Il Sudan è dilaniato da una guerra civile tra l'esercito regolare e le Forze di supporto rapido (Rsf), un gruppo paramilitare, che ha causato una delle maggiori crisi umanitarie al mondo. Le accuse reciproche di sostegno esterno tra Paesi della regione, come Etiopia ed Emirati Arabi Uniti, sono frequenti e complicano gli sforzi diplomatici per una tregua."
   ],
