   "id": "z74e242ef",
   "sez": "musica",
   "titolo": "Olivia Rodrigo pubblica un singolo natalizio ispirato agli anni Ottanta",
   "orig": "Olivia Rodrigo's Christmas song sounds familiar... on purpose",
   "lead": "La cantante Olivia Rodrigo ha pubblicato il singolo natalizio \"Take Me Home (4 Christmas)\", richiedendo preventivamente il permesso alla band cult anni Ottanta The Waitresses per il riferimento sonoro voluto al loro stile. Il videoclip, ambientato dopo una festa con postumi da sbronza, vede la partecipazione dell'attrice Cynthia Nixon, nota per \"Sex and the City\", e del comico Ben Marshall del \"Saturday Night Live\".",
   "more": [
    "Chiedere il permesso a un'altra band per un riferimento musicale volontario, come fatto da Olivia Rodrigo con The Waitresses, è una prassi che evita possibili contestazioni legali sul plagio e riconosce pubblicamente l'influenza artistica di un brano precedente su una nuova canzone."
   ],
