   "id": "zc1a94bbd",
   "sez": "spazio",
   "titolo": "In una ex miniera d'oro del South Dakota si cercano le risposte sull'universo",
   "orig": "From gold rush to cosmic questions: a South Dakota mine and the search for the secrets of the universe",
   "lead": "Nella città minerara di Lead, in South Dakota, un'ex miniera d'oro ospita la costruzione del Deep Underground Neutrino Experiment (Dune), un esperimento scientifico con grandi rilevatori destinati ad analizzare i neutrini, particelle subatomiche la cui comprensione potrebbe aiutare a svelare alcuni dei misteri più profondi dell'universo. Lo riferisce The Guardian.",
   "more": [
    "I neutrini sono particelle subatomiche estremamente difficili da rilevare perché interagiscono raramente con la materia. Studiarli in profondità, al riparo dalle interferenze della radiazione cosmica superficiale, permette ai fisici di indagare fenomeni fondamentali come l'asimmetria tra materia e antimateria nell'universo."
   ],
