   "id": "z75721ff2",
   "sez": "dibattito",
   "titolo": "Regno Unito, le aziende dovranno pubblicare gli stipendi negli annunci di lavoro",
   "orig": "Firms told to publish salaries in job adverts ahead of new law",
   "lead": "Nel Regno Unito le aziende dovranno indicare gli stipendi negli annunci di lavoro, in base a una nuova legge annunciata dal governo. Secondo l'esecutivo, la misura aiuterà chi cerca lavoro e potrebbe contribuire a prevenire la discriminazione salariale. Il primo ministro, insieme al ministro Andy Burnham, ha presentato la norma come una delle \"piccole correzioni\" previste dal governo. Resta intanto aperta la questione del contratto sanitario da 330 milioni di sterline con Palantir, che i ministri intendono sostituire con un fornitore britannico, secondo quanto riportato dal governo.",
   "more": [
    "La trasparenza salariale è una misura già adottata in diversi Paesi europei per contrastare le disparità retributive, in particolare quelle di genere, obbligando i datori di lavoro a dichiarare pubblicamente gli stipendi offerti prima dell'assunzione, così da ridurre il margine di negoziazione sbilanciato a favore delle aziende."
   ],
