   "sez": "adolescenti",
   "titolo": "Il lancio di Artemis II ha disturbato i segnali GPS, secondo uno studio",
   "orig": "Artemis II rocket disrupted GPS signals, study finds",
   "lead": "Un gruppo di scienziati di Taiwan ha pubblicato uno studio secondo cui il lancio del razzo Artemis II ha provocato significative interruzioni ai segnali GPS, usati ad esempio dalle mappe sugli smartphone. Lo riferisce BBC Newsround.",
   "more": [
    "I lanci di razzi di grandi dimensioni possono alterare temporaneamente l'atmosfera superiore, interferendo con i segnali satellitari usati dal sistema GPS per la navigazione. Questi effetti sono generalmente temporanei ma vengono studiati per capire meglio l'impatto delle missioni spaziali sulle infrastrutture tecnologiche terrestri."
   ],
