   "sez": "sport",
   "titolo": "Il giapponese Kozo Tashima si candida alla presidenza della FIFA",
   "orig": "Who is Kozo Tashima, the Japanese official running for FIFA presidency?",
   "lead": "Il dirigente giapponese Kozo Tashima, 68 anni, ha annunciato la candidatura alla presidenza della FIFA, sfidando l'attuale presidente Gianni Infantino alle elezioni previste al 77° Congresso FIFA a Rabat nel marzo prossimo. Tashima, sostenuto dalla Federazione calcistica giapponese, ha una lunga carriera come giocatore, allenatore e dirigente ed è descritto come una figura affidabile che punta a portare \"integrità\" nell'organizzazione calcistica mondiale.",
   "more": [
    "La FIFA, l'organo che governa il calcio mondiale, ha attraversato negli anni passati scandali legati a corruzione e gestione opaca. Gianni Infantino guida l'organizzazione dal 2016; una sua eventuale sfida da parte di un candidato asiatico come Tashima rappresenterebbe una novità significativa nella storia dell'elezione presidenziale."
   ],
