   "sez": "economia",
   "titolo": "Stati Uniti e Turkmenistan rafforzano i legami economici",
   "orig": "Expanding U.S.–Turkmenistan Ties: Envoy and Business Group Visit Ashgabat",
   "lead": "Un alto diplomatico statunitense e una delegazione di uomini d'affari americani hanno visitato Ashgabat per approfondire i rapporti economici e diplomatici tra Stati Uniti e Turkmenistan. La visita si inserisce in un percorso di dialogo bilaterale orientato a favorire investimenti e scambi commerciali tra i due paesi. Non vengono forniti ulteriori dettagli su accordi specifici raggiunti durante l'incontro. Lo riferisce The Times of Central Asia.",
   "more": [
    "Il Turkmenistan, ricco di risorse di gas naturale, ha storicamente mantenuto una politica di neutralità e relazioni economiche limitate con l'Occidente. Negli ultimi anni Washington ha intensificato i contatti con i paesi dell'Asia centrale per diversificare le relazioni commerciali nella regione."
   ],
