   "id": "zfcce602c",
   "sez": "dibattito",
   "titolo": "Attivisti forzano i cancelli del cantiere di un data center Microsoft ad Amsterdam",
   "orig": "Activisten breken door de hekken van terrein datacenter Microsoft in Amsterdam",
   "lead": "Decine di attivisti sono entrati nell'area del quartiere Sloterdijk di Amsterdam dove è previsto un data center Microsoft, forzando i cancelli del cantiere. La protesta, organizzata dall'associazione Fossielvrij NL insieme al gruppo Geef Tegengas, contesta la costruzione dell'infrastruttura, ritenuta dai manifestanti dannosa per l'ambiente a causa dell'elevato consumo energetico e idrico dei data center. Alcuni manifestanti erano già presenti sul sito prima dell'inizio ufficiale della manifestazione, fissato per mezzogiorno. Diverse persone sono state arrestate durante l'azione.",
   "more": [
    "I data center necessari per l'intelligenza artificiale e il cloud computing richiedono grandi quantità di energia e acqua per il raffreddamento dei server. In Europa crescono le proteste di movimenti ambientalisti contro nuovi impianti, soprattutto quando realizzati da grandi aziende tecnologiche come Microsoft, Google o Amazon, accusate di aggravare la crisi climatica e la pressione sulle risorse locali."
   ],
