   "id": "z5e8c70d0",
   "sez": "organizzazioni",
   "titolo": "Il Consiglio UE rinvia di un anno le regole di monitoraggio del metano",
   "orig": "Methane regulation: Council agrees to postpone monitoring rules for one year",
   "lead": "Il Consiglio dell'Unione europea ha raggiunto un accordo sulla propria posizione riguardo a modifiche mirate al regolamento sul metano, decidendo di posticipare di un anno le regole di monitoraggio legate alle importazioni di combustibili fossili. La decisione riguarda le norme che obbligano i produttori e importatori a rendicontare le emissioni di metano lungo la catena di fornitura. Il rinvio concede più tempo agli operatori per adeguarsi ai nuovi obblighi prima della loro piena applicazione.",
   "more": [
    "Il regolamento europeo sul metano, approvato per ridurre le emissioni di questo potente gas serra nel settore energetico, impone controlli e rendicontazioni anche sui combustibili fossili importati nell'UE. Il metano ha un effetto climatico molto più intenso della CO2 nel breve periodo, rendendo la sua riduzione una priorità nelle politiche ambientali europee."
   ],
