   "lead": "Il tradizionale Festival del Libro di Riga è iniziato oggi, 6 novembre, e si svolgerà anche domani, 7 novembre, presso la Biblioteca Nazionale della Lettonia, offrendo un ricco programma di eventi dedicati alla lettura e all'editoria. Lo riferisce LSM.",
