   "id": "z95348768",
   "sez": "italia",
   "titolo": "L'85% dei romani ama il proprio quartiere, nonostante traffico e affitti alti",
   "orig": "«Un'ora al giorno nel traffico, affitti a 1000 euro e sicurezza \"peggiorata\" in 5 anni». Ma l'85% dei romani ama il proprio quartiere",
   "lead": "Un'indagine riportata dal Messaggero mostra che l'85% dei residenti di Roma apprezza il proprio quartiere, nonostante le difficoltà quotidiane: un'ora al giorno trascorsa nel traffico, affitti che raggiungono i 1000 euro mensili e una percezione di sicurezza peggiorata negli ultimi cinque anni. Secondo i dati, i romani tendono a valutare positivamente la vita di quartiere, fatta di strade conosciute, negozi abituali e relazioni di vicinato, mentre il giudizio si fa più critico quando lo sguardo si allarga all'intera città. Lo riferisce Il Messaggero.",
   "more": [
    "Le grandi città italiane, Roma in particolare, affrontano da anni problemi legati a traffico, costo degli alloggi e percezione della sicurezza urbana. Le indagini sulla qualità della vita spesso rilevano un divario tra il giudizio positivo sul proprio quartiere e quello più negativo sulla città nel suo complesso, un fenomeno comune in molte metropoli."
   ],
