   "sez": "economia",
   "titolo": "La società olandese Robeco punta a espandersi a Hong Kong",
   "orig": "Dutch asset manager Robeco planning to expand presence in Hong Kong",
   "lead": "La società di gestione patrimoniale olandese Robeco prevede di espandere la propria presenza a Hong Kong per sfruttare la forte crescita della ricchezza nella regione Asia-Pacifico, ha dichiarato l'amministratrice delegata Karin van Baardwijk. L'azienda, con sede a Rotterdam e asset dei clienti pari a 464 miliardi di dollari a giugno, si trasferirà presto in un ufficio più grande. Secondo van Baardwijk, l'Asia resta uno dei mercati di ricchezza in più rapida crescita e Hong Kong continua a dimostrare il suo ruolo di centro finanziario globale.",
   "more": [
    "Hong Kong è uno dei principali centri finanziari dell'Asia, con un ruolo storico di porta d'accesso agli investimenti sul mercato cinese e asiatico. Negli ultimi anni la città ha attraversato fasi di instabilità politica ed economica, ma continua ad attrarre società di gestione patrimoniale internazionali grazie alla crescita della ricchezza privata nella regione."
   ],
