   "orig": "Luxembourg banking sector expands with two new licences",
   "lead": "Il Lussemburgo ha concesso due nuove licenze bancarie, a Swiss Life Banque Privée Luxembourg e Banca March Luxembourg, portando il numero totale di banche presenti nel Granducato da 118 a 120. L'espansione del settore bancario lussemburghese conferma l'attrattività del paese come centro finanziario europeo per nuovi istituti privati. Lo riferisce Luxembourg Times.",
