   "id": "z536c67b9",
   "sez": "economia",
   "titolo": "Record di aziende di Hong Kong all'expo delle importazioni di Shanghai",
   "orig": "Record 400-plus HK firms join Shanghai import expo",
   "lead": "Un numero record di oltre 400 aziende di Hong Kong partecipa quest'anno all'Esposizione internazionale delle importazioni della Cina a Shanghai, nella speranza di usare l'evento come trampolino di lancio verso il mercato cinese continentale. Tra le prime volte espositrici figura una società di contabilità di Hong Kong, che ha registrato un aumento del 30% di clienti del continente interessati a espandersi all'estero. Il direttore della divisione Greater China dell'azienda, Man Law, ha dichiarato che l'espansione all'estero è ormai una necessità pratica più che una tendenza. Lo riferisce RTHK.",
   "more": [
    "La China International Import Expo, lanciata nel 2018 su iniziativa del governo cinese, è una delle principali vetrine mondiali per aziende straniere che vogliono accedere al mercato cinese, e riflette gli sforzi di Pechino per presentarsi come mercato aperto agli scambi internazionali."
   ],
