   "id": "z4c7e9ade",
   "sez": "mondo",
   "titolo": "Nuova Zelanda, testa a testa tra Nazionali e Laburisti alle elezioni",
   "orig": "Não há favoritos nas eleições legislativas da Nova Zelândia",
   "lead": "I sondaggi per le elezioni legislative di sabato in Nuova Zelanda indicano un sostanziale pareggio tecnico tra il Partito Nazionale, attualmente al governo, e il Partito Laburista, all'opposizione. Secondo le proiezioni, saranno i partiti minori a decidere chi formerà il prossimo governo del paese. Il voto si svolge in un clima di incertezza politica, con nessuno dei due principali schieramenti in vantaggio netto. Lo riferisce Público.",
   "more": [
    "La Nuova Zelanda utilizza un sistema elettorale proporzionale misto che favorisce la formazione di coalizioni tra i due maggiori partiti e le formazioni minori, spesso decisive per la composizione del governo, come già avvenuto in diverse tornate elettorali precedenti nel paese."
   ],
