   "orig": "Duchess of Sussex’s estranged half-brother ‘person of interest’ in child sexual abuse inquiry",
   "lead": "Thomas Markle Jr, fratellastro della duchessa di Sussex Meghan Markle, è stato indicato come 'persona di interesse' nell'indagine delle autorità filippine su immagini di abuso sessuale su minori che coinvolgono il padre di Meghan, Thomas Markle Sr. Lo ha dichiarato il segretario agli Interni e al governo locale delle Filippine, Jonvic Remulla, in conferenza stampa a Manila, secondo cui ci sarebbero 'segnali che indicano il coinvolgimento' dell'uomo nel caso. Markle Jr non è ancora considerato formalmente sospettato nell'indagine.",
