   "titolo": "Ritirata la denuncia contro il nipote di Dolly Parton sull'eredità",
   "orig": "Dolly Parton's manager moves to drop complaint against late singer's nephew",
   "lead": "Il manager storico di Dolly Parton ha ritirato giovedì la denuncia presentata contro il nipote della cantante, scomparsa in agosto, che lavorava come capo della sicurezza della star. Il manager, che amministra anche l'eredità della cantante, l'accusava di aver minacciato il patrimonio di Parton e i suoi dipendenti. Secondo fonti tedesche, la disputa sull'eredità milionaria della star country non sarà quindi portata in tribunale, segno di un accordo raggiunto tra le parti. Lo riferisce CBC News.",
