   "titolo": "Il Cremlino accusa l'Europa di non decidere chi la rappresenterà nei negoziati",
   "orig": "Kremlin Accuses Europe of Struggling to Decide Who Will Represent It in Future Security Talks",
   "lead": "Il portavoce del Cremlino Dmitry Peskov ha accusato venerdì l'Europa di non riuscire a decidere chi la rappresenterà nei futuri colloqui sulla sicurezza legati a un possibile accordo sull'Ucraina. Secondo Peskov, i messaggi provenienti dai funzionari di Bruxelles indicano che l'Europa resta ancora riluttante a impegnarsi in discussioni serie con la Russia. L'accusa arriva nel contesto dei negoziati in corso per porre fine al conflitto in Ucraina. Lo riferisce Moscow Times.",
   "more": [
    "Da quando è iniziata l'invasione russa dell'Ucraina nel 2022, l'Unione Europea ha più volte faticato a presentare una posizione unitaria nei negoziati internazionali, complicata dalla necessità di coordinare le posizioni dei singoli Stati membri."
   ],
