   "id": "z89e6a6b3",
   "sez": "mondo",
   "titolo": "L'UE invita i cittadini a prepararsi con un kit di sopravvivenza da 72 ore",
   "orig": "EU urges citizens to prepare a 72-hour “survival kit” (POLL)",
   "lead": "La Commissione europea e la Protezione civile hanno raccomandato ai cittadini dell'Unione Europea di preparare un kit di sopravvivenza da 72 ore, secondo linee guida diffuse il 3 novembre 2026 nell'ambito della preparazione alle emergenze. Il motivo specifico della raccomandazione non è stato precisato nelle comunicazioni ufficiali. Ogni famiglia dell'UE viene invitata a garantirsi scorte sufficienti per affrontare in autonomia le prime 72 ore di un'eventuale emergenza. Lo riferisce Keep Talking Greece.",
   "more": [
    "Le raccomandazioni UE sulla preparazione civile alle emergenze rientrano in una strategia più ampia di resilienza adottata negli ultimi anni dall'Unione, che comprende scorte alimentari, acqua, medicinali e strumenti di comunicazione, pensata per rispondere a crisi diverse, da calamità naturali a blackout energetici."
   ],
